"""Writes docs/research/interpretation_benchmark.md from reports/ai/interpretation-bench-<split>.json and interpretation-latency.json: `tools/.venv/Scripts/python.exe tools/bench/interpretation_report.py [--check]` (p1-ai-language-s14, ADR-0022).
Every number on the page comes from those files; counts keep their denominators."""
from __future__ import annotations

import json
import sys
from pathlib import Path

sys.stdout.reconfigure(encoding="utf-8")
ROOT = Path(__file__).resolve().parents[2]
R = ROOT / "reports" / "ai"
OUT = ROOT / "docs" / "research" / "interpretation_benchmark.md"
SYSTEMS = (("classifier_route_as_served", "Classifier route, as served (no state)"), ("classifier_route_after_window_rule", "Classifier route, then the engine's window rule"), ("interpretation_in_window", "Interpretation path, shipped (cap 0.05, evidence accepted by the engine)"))


def render() -> str:
    D = {s: json.loads((R / f"interpretation-bench-{s}.json").read_text(encoding="utf-8")) for s in ("dev", "test", "test2")}
    lat = json.loads((R / "interpretation-latency.json").read_text(encoding="utf-8"))
    L = ["# Context-aware interpretation of trainee speech against the classifier route (ADR-0022)", "",
         "_Generated by `tools/bench/interpretation_report.py` from `reports/ai/interpretation-bench-*.json` and `interpretation-latency.json`; do not edit by hand. **PRELIMINARY: synthetic.** `tests/action_bench_v1` is written by one author family and labelled by construction; it is not independent evidence of generalisation, "
         "and a result on it can never switch the `speech_interpretation` gate on. The gate reads the independent set (EX-01), which does not exist. Dev is where the rules could change; they were not changed after any split was scored; test and test2 were scored once. The test split was already used to widen the assertion check (ADR-0020).", "",
         "## What was run, and what the rows' state is", "",
         "The benchmark rows carry no scenario state, so `tools/bench/interpretation_bench.py` gives each row a state from the engine's own rule: the first workflow step of a behaviour window of `content/assessment/mapping.json` that lists the row's act (every step for the critical acts no behaviour lists), a waiting patient question for ANSWER_QUESTION rows and a waiting read-back for CLOSED_LOOP rows. "
         "This is a derived state, not a recorded one: it shows that the rules work as designed on these rows; it does not show how trainees' speech distributes over real steps. No language model is used; the candidate generator is the retained classifier gate (ADR-0020), whose decisions on the same rows are reproduced exactly (0 differences on 1,464 rows).", "",
         "## Legitimate and false credit on identical rows", "",
         "| Split | System | Offers | Right | Credited precision | Legitimate recall (of 140) | Critical offered (of 40) | Non-assertive offered (of 300) |", "|---|---|---|---|---|---|---|---|"]
    for s, d in D.items():
        for k, name in SYSTEMS:
            v = d[k]
            L.append(f"| {s} | {name} | {v['offers']} | {v['offers_right']} | {v['credited_precision']} | {v['legitimate_recall']} | {v['critical_false_credit']} | {v['non_assertive_false_credit']} |")
    L += ["", "On 19 October 2026 the interpretation path equalled the classifier route after the engine's window rule (it removed credit, never added it). On 20 October 2026 two changes were made on evidence (`docs/research/recall_diagnosis.md`): the head's critical-mass cap went from 0.03 to 0.05 and the engine's per-act evidence thresholds became the classifier's own calibrated thresholds (the 0.8 placeholder had been refusing evidence the gate credited). The rows above count evidence ACCEPTED by the engine. The refusals the route cannot make without state are unchanged:", "",
          "| Split | Legitimate rows put outside their window | Route would credit | Route after the engine's window rule | Interpretation offered the row's own act | Rows needing a waiting question or read-back | Route credited | Interpretation without the context | Interpretation with it |", "|---|---|---|---|---|---|---|---|---|"]
    for s, d in D.items():
        o, w = d["out_of_window"], d["without_pending_question_or_readback"]
        L.append(f"| {s} | {o['legitimate_rows_with_an_outside_step']} | {o['route_as_served_would_offer_its_credited_act']} | {o['route_after_window_rule_offered_the_rows_own_act']} | {o['interpretation_offered_the_rows_own_act']} | {w['rows']} | {w['route_credited_the_rows_own_act']} | {w['interpretation_offered_the_rows_own_act']} | {w['with_the_context_offered_the_rows_own_act']} |")
    L += ["", "## Decisions on the 140 legitimate rows (state given)", "", "| Split | Offered as evidence | Clarification | Abstained | Menu | Legitimate rejection (neither offered nor asked) | Why the missed ones were missed |", "|---|---|---|---|---|---|---|"]
    for s, d in D.items():
        i = d["interpretation_in_window"]
        dec = i["legitimate_decisions"]
        L.append(f"| {s} | {dec.get('OFFER_EVIDENCE', 0)} | {dec.get('CLARIFY', 0)} | {dec.get('ABSTAIN', 0)} | {dec.get('MENU', 0)} | {i['legitimate_rejection_rate']} | {', '.join(f'{k} {v}' for k, v in i['reasons_for_missed_legit'].items())} |")
    L += ["", "Most of the sentences still missed are refused by the classifier gate's critical-mass cap, now 0.05 (the head gives 5 percent or more to a critical act), not by the context rules. Removing the cap would let 10 sentences of evasive critical content or non-performed speech through (`reports/ai/recall-safety-panel.json`), and no signal the path has separates them from the legitimate sentences that sit at the same critical mass; see the diagnosis.", "",
          "## Critical content", "", "| Split | Critical rows | Offered in any context | Menu pointing at the verified actions |", "|---|---|---|---|"]
    for s, d in D.items():
        c = d["critical"]
        L.append(f"| {s} | {c['rows']} | {c['offered_in_any_condition']} | {c['menu_with_verified_action_pointer']} |")
    L += ["", "## Labels on the 188 core rows (offered act, else ABSTAIN), forced comparison", "", "| Split | System | Accuracy | Macro-F1 |", "|---|---|---|---|"]
    for s, d in D.items():
        for k, name in SYSTEMS:
            v = d[k]["label_view_core"]
            L.append(f"| {s} | {name} | {v['accuracy']} | {v['macro_f1']} |")
    L += ["", "Accuracy here counts an abstention as wrong, so it measures coverage as much as correctness. Per-class precision, recall and F1 and the confusion matrices of every system are in the JSON reports.", "",
          "## Failure examples (test2)", ""]
    ex = D["test2"]["examples"]
    L += [f"**Wrong offers** ({D['test2']['example_counts']['wrong_offers']} in test2): " + ("none." if not ex["wrong_offers"] else "")]
    for e in ex["wrong_offers"]:
        L.append(f"* \"{e['text']}\" - truth {e['act']} ({e['category']}); offered {e['offer']}")
    L += ["", f"**Missed legitimate sentences** ({D['test2']['example_counts']['missed_legitimate']} in test2; first {len(ex['missed_legitimate'])}):", ""]
    for e in ex["missed_legitimate"]:
        L.append(f"* \"{e['text']}\" - truth {e['act']} ({e['category']}); {e['decision']} {e['reasons']}; the route credited: {e['route']}")
    wa = lat["warm_alone_ms"]
    wl = lat["warm_while_4b_generates_ms"]
    pr = lat["patient_reply_ms"]
    v = lat["voice_workflow_from_reports"]
    L += ["", "## Latency (this desktop: GTX 1660 SUPER, Ryzen 5 2600; the headset and Unity were not measured)", "", "| Measure | Median | p95 | n |", "|---|---|---|---|",
          f"| One interpretation, warm, nothing else running | {wa['whole']['median']} ms | {wa['whole']['p95']} ms | {wa['whole']['n']} |",
          f"| of which the embedding call | {wa['embedding_call']['median']} ms | {wa['embedding_call']['p95']} ms | {wa['embedding_call']['n']} |",
          f"| of which the heads and rules | {wa['heads_and_rules']['median']} ms | {wa['heads_and_rules']['p95']} ms | {wa['heads_and_rules']['n']} |",
          f"| One interpretation while the 4B model is generating a reply | {wl['whole']['median']} ms | {wl['whole']['p95']} ms | {wl['whole']['n']} |",
          f"| A 40-token patient reply alone | {pr['alone']['median']} ms | {pr['alone']['p95']} ms | {pr['alone']['n']} |",
          f"| The same reply while interpretations are fired continuously ({pr['interpretations_completed_meanwhile']} completed meanwhile) | {pr['with_interpretations_firing_continuously']['median']} ms | {pr['with_interpretations_firing_continuously']['p95']} ms | {pr['with_interpretations_firing_continuously']['n']} |",
          f"| Embedding model cold start (unloaded, then the first interpretation) | {lat['embedder_cold_start_ms']} ms | | 1 |", "",
          f"From committed reports, not re-measured: recognition p95 {v['asr_p95_s']} s, the grounded patient reply p95 {v['patient_reply_p95_s']} s, the first spoken sentence p95 {v['first_spoken_sentence_p95_s']} s. The interpretation runs beside the reply, not in it. The sum of those three p95s is {v['reply_path_sum_of_p95s_s']} s against the {v['round_trip_target_p95_s']} s target; a sum of percentiles is an upper bound, and the real figure is device check DC-08 (Sannan). This work does not change that path.", "",
          "## Limits", "",
          "* Synthetic rows from one author family, labelled by construction; the state of each row is derived from the engine's rule, not recorded from play. No independent human-labelled set exists (EX-01, EX-18); nothing here shows how the path behaves on real trainee speech.",
          "* The context rules remove credit, never add it; the recall gain over the classifier route comes from the revised cap and the engine thresholds (docs/research/recall_diagnosis.md), whose safety was judged on synthetic panels. The acts ANSWER_QUESTION and CLOSED_LOOP are offered only with a waiting patient question or a critical result awaiting acknowledgement, which the benchmark ASSUMES for those rows; the real engine records the second rarely, so the gain on CLOSED_LOOP rows is not evidence of the same gain in play.",
          "* The Qwen 4B evaluator was NOT used (docs/research/rubric_evaluator.md); it is out of the live path (ADR-0022). Context-conditioned Qwen was therefore still not measured with real per-row context.",
          "* Latency is one desktop; the headset, the microphone chain, Unity and the laptop were not measured.", ""]
    return "\n".join(L) + "\n"


def main(argv: list[str]) -> int:
    text = render()
    if "--check" in argv:
        ok = OUT.exists() and OUT.read_text(encoding="utf-8") == text
        print("interpretation benchmark page " + ("current" if ok else "OUT OF DATE: run tools/bench/interpretation_report.py"))
        return 0 if ok else 1
    OUT.write_text(text, encoding="utf-8", newline="\n")
    print("wrote", OUT.relative_to(ROOT).as_posix())
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
